import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_ANIMAL, MODELO_REFUGIO, TABLA_ANIMALES } from '../../models/refugio-animal.model.mjs';

export async function crearAnimalRepository(animal) {
  await MODELO_ANIMAL.build(PutItemCommand)
    .item(animal)
    .options({ condition: { attr: 'animalId', exists: false } })
    .send();
}

export async function listarAnimalesRepository() {
  const { Items = [] } = await TABLA_ANIMALES.build(ScanCommand)
    .entities(MODELO_ANIMAL)
    .options({ consistent: true })
    .send();
  return Items;
}

